-- ============================================================================
-- eia_plants_district: Spatial crosswalk matching EIA Form 860 power plants
-- to US Congressional Districts across decennial redistricting cycles (103rd-114th)
-- Generated by: analysis/eia-plants-district.R via sf spatial join
-- ============================================================================

DROP TABLE IF EXISTS eia_plants_district;

CREATE TABLE eia_plants_district (
    plant_code INTEGER NOT NULL,
    congress INTEGER NOT NULL,
    state_code TEXT NOT NULL,
    district_number INTEGER NOT NULL DEFAULT 0,
    latitude REAL,
    longitude REAL,
    PRIMARY KEY (plant_code, congress),
    FOREIGN KEY (plant_code) REFERENCES eia_plants(plant_code),
    FOREIGN KEY (state_code) REFERENCES states(state_code)
);

CREATE INDEX IF NOT EXISTS idx_eia_plants_dist_cong ON eia_plants_district(congress, state_code, district_number);
CREATE INDEX IF NOT EXISTS idx_eia_plants_dist_plant ON eia_plants_district(plant_code);
